<?php
use App\Core\{DB,Security};
use App\Models\{Ticket,TicketTime,TicketHistory,TicketClosure,Project,Release,Workflow};
use App\Services\Query;

$tp=Project::save(['name'=>'Suivi complet','key'=>'TR'.strtoupper(bin2hex(random_bytes(3)))]);
$tpOther=Project::save(['name'=>'Autre livraison','key'=>'TX'.strtoupper(bin2hex(random_bytes(3)))]);
$tu=DB::insert("INSERT INTO users(email,name,password_hash,role,verified_at) VALUES(?,?,?,'member',UTC_TIMESTAMP())",['time.'.bin2hex(random_bytes(4)).'@example.com','Collaborateur temps',Security::password('Tests-Time-2026!')]);
$tv=DB::insert("INSERT INTO users(email,name,password_hash,role,verified_at) VALUES(?,?,?,'viewer',UTC_TIMESTAMP())",['read.'.bin2hex(random_bytes(4)).'@example.com','Lecture temps',Security::password('Tests-Time-2026!')]);
$tt=Ticket::create($tp,['title'=>'Suivi de réalisation','estimated_hours'=>'10','progress_percent'=>60],$uid);
$externalTicket=Ticket::create($tpOther,['title'=>'Demande externe auditée'],$uid,'demandeur@example.net');
$externalHistory=TicketHistory::page($externalTicket)['entries'][0];
check($externalHistory['actor_id']===null && $externalHistory['source']==='external','création externe ne se fait pas passer pour le propriétaire du formulaire');
$t=Ticket::find($tt);
check($t['remaining_hours']==='4.00' && (float)$t['spent_hours']===0.0,'reste calculé sur estimation totale et avancement');
$entry=TicketTime::save($tt,['hours'=>'7,25','worked_on'=>gmdate('Y-m-d'),'note'=>'Analyse et réalisation'],$tu,$t['version']);
check($entry['ticket']['spent_hours']==='7.25' && $entry['ticket']['remaining_hours']==='4.00','temps passé indépendant du reste et du pourcentage');
check($entry['ticket']['progress_percent']===60,'saisie du temps ne modifie pas l’avancement');
rejects(fn()=>TicketTime::save($tt,['hours'=>'1','worked_on'=>gmdate('Y-m-d')],$tu,$t['version']),'saisie obsolète refusée sans doublon');
check(TicketTime::page($tt)['total']===1,'échec de version ne crée aucune saisie');
rejects(fn()=>TicketTime::save($tt,['hours'=>'0','worked_on'=>gmdate('Y-m-d')],$tu,$entry['ticket']['version']),'durée nulle refusée');
rejects(fn()=>TicketTime::save($tt,['hours'=>'24.01','worked_on'=>gmdate('Y-m-d')],$tu,$entry['ticket']['version']),'durée journalière incohérente refusée');
rejects(fn()=>TicketTime::save($tt,['hours'=>'1','worked_on'=>gmdate('Y-m-d',time()+86400)],$tu,$entry['ticket']['version']),'temps futur refusé');
rejects(fn()=>TicketTime::save($tt,['hours'=>'1','worked_on'=>gmdate('Y-m-d')],$tv,$entry['ticket']['version']),'compte lecture seule ne saisit pas de temps');
$otherTime=TicketTime::save($tt,['hours'=>'1','worked_on'=>gmdate('Y-m-d')],$uid,$entry['ticket']['version']);
rejects(fn()=>TicketTime::save($tt,['hours'=>'2','worked_on'=>gmdate('Y-m-d')],$tu,$otherTime['ticket']['version'],(int)$otherTime['entry']['id']),'collaborateur ne corrige pas le temps d’autrui');
$entry=TicketTime::save($tt,['hours'=>'6.5','worked_on'=>gmdate('Y-m-d'),'note'=>'Correction du relevé'],$uid,$otherTime['ticket']['version'],(int)$entry['entry']['id']);
check($entry['ticket']['spent_hours']==='7.50','administrateur peut corriger une saisie en conservant son auteur');
check((int)$entry['entry']['user_id']===$tu,'auteur de la saisie conservé après correction');
$deleted=TicketTime::save($tt,[],$uid,$entry['ticket']['version'],(int)$entry['entry']['id'],true);
check($deleted['ticket']['spent_hours']==='1.00' && TicketTime::page($tt)['total']===1,'suppression retire uniquement le temps actif');
$history=TicketHistory::page($tt);
check($history['entries'][0]['action']==='time.deleted' && $history['entries'][0]['changes'][0]['before']['hours']==='6.50','ancienne durée conservée dans l’historique immuable');
Ticket::patch($tt,['progress_percent'=>100],$uid,Ticket::find($tt)['version']);check(Ticket::find($tt)['remaining_hours']==='0.00','avancement 100 donne zéro heure restante');
Ticket::patch($tt,['progress_percent'=>0,'estimated_hours'=>null],$uid,Ticket::find($tt)['version']);check(Ticket::find($tt)['remaining_hours']===null,'absence d’estimation conserve reste inconnu');
Ticket::patch($tt,['estimated_hours'=>'0'],$uid,Ticket::find($tt)['version']);check(Ticket::find($tt)['remaining_hours']==='0.00','estimation zéro distincte de l’absence');
Ticket::patch($tt,['estimated_hours'=>'0.01','progress_percent'=>50],$uid,Ticket::find($tt)['version']);check(Ticket::find($tt)['remaining_hours']==='0.01','arrondi décimal MySQL du reste à deux décimales');
Ticket::patch($tt,['estimated_hours'=>'10','progress_percent'=>60,'title'=>'Titre historisé'],$uid,Ticket::find($tt)['version']);
$changes=TicketHistory::page($tt)['entries'][0]['changes'];$titleChange=array_values(array_filter($changes,fn($c)=>$c['field']==='title'))[0];
check($titleChange['before']==='Suivi de réalisation' && $titleChange['after']==='Titre historisé','historique conserve les valeurs avant et après');
$beforeHistory=TicketHistory::page($tt)['total'];Ticket::patch($tt,['estimated_hours'=>'10,00'],$uid,Ticket::find($tt)['version']);
check(TicketHistory::page($tt)['total']===$beforeHistory,'normalisation des décimales évite les faux changements');
$row=Query::tickets($tp,[])[0];$workload=Query::teamWorkload($tp,[])[0];
check($row['remaining_hours']==='4.00' && $workload['remaining_hours']==='4.00' && $workload['spent_hours']==='1.00','liste et rapport partagent le même calcul');
DB::run('SAVEPOINT tracking_rollback');$beforeHistory=TicketHistory::page($tt)['total'];$beforeSpent=Ticket::find($tt)['spent_hours'];
TicketTime::save($tt,['hours'=>'2','worked_on'=>gmdate('Y-m-d')],$tu,Ticket::find($tt)['version']);DB::run('ROLLBACK TO SAVEPOINT tracking_rollback');
check(TicketHistory::page($tt)['total']===$beforeHistory && Ticket::find($tt)['spent_hours']===$beforeSpent,'rollback annule temps et historique ensemble');
$release=Release::save($tp,['name'=>'2.4.0','description'=>'Objectif de livraison','target_date'=>'2026-12-01'],$uid);
Ticket::patch($tt,['release_id'=>$release['id']],$uid,Ticket::find($tt)['version']);
check(Query::count($tp,['release'=>$release['id']])===1,'filtre par version cible');
rejects(fn()=>Ticket::create($tpOther,['title'=>'Version étrangère','release_id'=>$release['id']],$uid),'affectation à une version d’un autre projet refusée');
check(Release::find($release['id'])['delivery_state']['production']===null,'association du ticket ne déclare pas une livraison');
$release=Release::deliver($release['id'],['environment'=>'staging','outcome'=>'success','reference'=>'v2.4.0-rc1'],$uid,$release['version']);
check($release['delivery_state']['staging']['outcome']==='success' && $release['delivery_state']['production']===null,'préproduction et production restent indépendantes');
rejects(fn()=>Release::deliver($release['id'],['environment'=>'production','outcome'=>'success','reference'=>'v2.4.0'],$uid,1),'livraison obsolète refusée');
check(Release::deliveries($release['id'])['total']===1,'livraison obsolète ne duplique pas l’historique');
$release=Release::deliver($release['id'],['environment'=>'production','outcome'=>'failed','reference'=>'v2.4.0'],$uid,$release['version']);
$release=Release::deliver($release['id'],['environment'=>'production','outcome'=>'success','reference'=>'v2.4.0'],$uid,$release['version']);
$release=Release::deliver($release['id'],['environment'=>'production','outcome'=>'rolled_back','reference'=>'v2.3.9','note'=>'Repli après contrôle'],$uid,$release['version']);
check($release['delivery_state']['production']['outcome']==='rolled_back' && Release::deliveries($release['id'])['total']===4,'retour arrière conserve les livraisons précédentes');
$release=Release::save($tp,['version'=>$release['version'],'target_date'=>null,'archived'=>true],$uid,$release['id']);
check($release['target_date']===null && Release::page($tp,0,50,true)['total']===1,'date cible effaçable et version archivable');
rejects(fn()=>Release::deliver($release['id'],['environment'=>'staging','outcome'=>'success','reference'=>'v2.4.0'],$uid,$release['version']),'version archivée ne reçoit pas de nouvelle livraison');
Ticket::patch($tt,['priority'=>'high'],$uid,Ticket::find($tt)['version']);
rejects(fn()=>Ticket::create($tp,['title'=>'Version archivée','release_id'=>$release['id']],$uid),'nouvelle affectation à une version archivée refusée');
check(Ticket::find($tt)['release_name']==='2.4.0','archivage conserve les tickets déjà affectés');
Project::save(['require_ticket_validation'=>true],$tp);
$lineTicket=Ticket::create($tp,['title'=>'Retours à la ligne','description'=>"Première ligne\nDeuxième ligne"],$uid);
$lineReview=TicketClosure::review($lineTicket,true,'Contrôlé',$tu,Ticket::find($lineTicket)['version']);
Ticket::patch($lineTicket,['description'=>"Première ligne\r\nDeuxième ligne",'status'=>'done'],$uid,$lineReview['version']);
check(Ticket::find($lineTicket)['validation_state']==='approved' && Ticket::find($lineTicket)['description']==="Première ligne\nDeuxième ligne",'retours CRLF du navigateur ne modifient pas le contenu validé');
check(!in_array('description',array_column(TicketHistory::page($lineTicket,0,1)['entries'][0]['changes'],'field'),true),'fermeture avec retours CRLF ne crée pas de faux historique de description');
rejects(fn()=>Ticket::create($tp,['title'=>'Clôture directe','status'=>'done'],$uid),'validation obligatoire aussi à la création');
rejects(fn()=>Ticket::patch($tt,['status'=>'done'],$uid,Ticket::find($tt)['version']),'clôture sans validation refusée');
rejects(fn()=>TicketClosure::review($tt,false,'',$tu,Ticket::find($tt)['version']),'demande de reprise exige une raison');
rejects(fn()=>TicketClosure::review($tt,true,'',$tv,Ticket::find($tt)['version']),'lecture seule ne peut pas valider');
$t=TicketClosure::review($tt,false,'Ajouter un contrôle mobile',$tu,Ticket::find($tt)['version']);
check($t['validation_state']==='rejected' && $t['validation_note']==='Ajouter un contrôle mobile','demande de reprise conserve auteur et motif');
$t=TicketClosure::review($tt,true,'Contrôle effectué',$tu,$t['version']);
rejects(fn()=>TicketClosure::review($tt,true,'',$tu,$t['version']-1),'validation obsolète refusée');
Ticket::patch($tt,['description'=>'Modification après validation'],$uid,$t['version']);$t=Ticket::find($tt);
check($t['validation_state']==='pending' && $t['validated_by']===null,'modification du contenu invalide la validation et ses métadonnées');
rejects(fn()=>Ticket::patch($tt,['status'=>'done'],$uid,$t['version']),'validation périmée ne permet pas de clôturer');
$t=TicketClosure::review($tt,true,'Nouveau contrôle',$tu,$t['version']);
Ticket::patch($tt,['status'=>'review'],$uid,$t['version']);$t=Ticket::find($tt);
check($t['validation_state']==='approved','transition seule conserve la validation');
Ticket::patch($tt,['status'=>'done','resolution'=>'fixed'],$uid,$t['version']);$t=Ticket::find($tt);
check($t['resolution']==='fixed' && $t['completed_at']!==null,'clôture validée conserve une résolution explicite');
check(Query::count($tp,['resolution'=>'fixed','validation'=>'approved'])===1,'filtres de résolution et validation');
Ticket::patch($tt,['status'=>'progress'],$uid,$t['version']);$t=Ticket::find($tt);
check($t['resolution']===null && $t['validation_state']==='pending' && $t['completed_at']===null,'réouverture réinitialise résolution et validation');
$wf=Workflow::get($tp);$wf=Workflow::save($tp,['version'=>$wf['version'],'action'=>'add_item','kind'=>'status','label'=>'Livré et clos','category'=>'done','icon'=>'check','color'=>'#15803d']);$doneCode=array_values(array_diff(array_keys($wf['items']['status']),array_keys(Ticket::STATUSES)))[0];
rejects(fn()=>Ticket::patch($tt,['status'=>$doneCode],$uid,$t['version']),'statut terminé personnalisé respecte la validation obligatoire');
$t=TicketClosure::review($tt,true,'Validé',$tu,$t['version']);Ticket::patch($tt,['status'=>$doneCode,'resolution'=>'duplicate'],$uid,$t['version']);
check(Ticket::find($tt)['resolution']==='duplicate','résolution appliquée aux statuts terminés personnalisés');
$historic=TicketHistory::page($tt,0,1);
check(count($historic['entries'])===1 && $historic['total']>1 && (int)$historic['entries'][0]['actor_id']===$uid,'historique paginé avec identité de l’acteur');
Ticket::archive($tt,true,$uid,Ticket::find($tt)['version']);
check(TicketHistory::page($tt,0,1)['entries'][0]['action']==='archived','archivage tracé avec ancienne valeur');
